TARGET_CHARS = 2000      # 目标块长
MAX_CHARS = 3200         # 超过则硬切
OVERLAP = 200            # 相邻块重叠，避免答案正好落在边界
MIN_CHARS = 200          # 过短的块并入前一块
# 🔴 折行片长（WRAP_LIMIT）的取值受两条硬约束，不能随手写 MAX_CHARS：
#   ① 片长必须 > OVERLAP：否则「重叠回退」一次要回退多片，回退跨度超过 OVERLAP，
#      block 边界不再落在片边界上 ⇒ 块无法表示成真实行区间（回指原文只能取整行，
#      必然多算内容）。
#   ② 片长必须 < TARGET_CHARS：否则单片就超阈值，flush 后回退取回的仍是同一片，
#      循环原地打转。实测旧代码在该形态下 max(chars) 达 MAX_CHARS+2200（5400 字符块）。
#   取 MAX_CHARS-OVERLAP：满足 ① 且有充裕余量，同时让「片+重叠」天然不超过 MAX_CHARS。
#   代价：超长单行的切块粒度变细（≈1900 而非 3200 字符），换来
#   「行号恒可回指 + 块长恒有界 + 覆盖无缺口」三者同时成立。
WRAP_LIMIT = MAX_CHARS - OVERLAP

_H_RE = re.compile(r"^(#{1,4})\s+(.+)$", re.M)


# ---------------------------------------------------------------- 分块

def _hard_wrap(line, limit):
    """把超长单行硬切成多行（**仅供切块用**，不再用于行号）。

    🔴 为什么必需：原文里常有「一整段没有换行」的长文本（提取器把段间换行吞掉）。
    旧实现按行遍历，遇到单行 > MAX_CHARS 时，重叠回退会把**同一行**再取回来，
    于是循环既不前进也不切分 ⇒ 产出与原文等长的巨型块（--selftest 实测 5400 字符未切）。

    ⚠️ 但它产出的是**合成行**：折断出来的行号与原文真实行号无关。
    旧版直接把合成行号当行号报出去 ⇒ 报出的行号可能**超过文件真实行数**，
    用户拿着它回原文定位会落到文件末尾之外（本库把「L3 原文层可回指文件:行号」
    当作检索层的前提，故这等于该前提失效）。见 split_chunks 的 _real()。
    """
    if len(line) <= limit:
        return [line]
    return [line[i:i + limit] for i in range(0, len(line), limit)]


def _wrap_index(raw_lines):
    """返回合成行表：每项 (成行起点, 成行终点, 成行所属真实行号 1-based)。

    终点是**排他**的，且该合成行的尾随换行不计入——这样片段链上「下一片起点 ==
    上一片终点」，切任何一段 [i0,i1) 都只需取 `wrap[i0][0] .. wrap[i1-1][1]`。
    🔴 若改用「到下一片起点」当终点，hard wrap 的第 1 片会把第 2 片一起吞掉
    （实测：只能取到 1/3 的正文，且块之间出现内容缺口）。

    两个映射都必须在此产生，它们是「行号必须真的能回到原文」的唯一实现点：
      · real_of[i]：第 i 条合成行属于原文第几行。hard wrap 把一行的多个碎片刻成
        连续合成行，故一个真实行号会被多个合成行共享——这正是「一次 chunk 跨越
        折断边界时取起始位置在原文中所属的行」所需的语义。
      · 起点/终点：合成行除了首片之外都不从原文行首开始，误用「原文行首下标」
        会把 chunk 正文切片切错（切到别人的内容，且块间出现缺口）。
    """
    rows, pos = [], 0
    for ri, rl in enumerate(raw_lines):
        for piece in _hard_wrap(rl, WRAP_LIMIT):
            rows.append((pos, pos + len(piece), ri + 1))
            pos += len(piece)
        pos += 1                       # 该真实行的换行符（split("\n") 序列的长度约定）
    return rows


def split_chunks(text, path, line_offset=0):
    """按 ## 标题切块，超长再按段落合并切分。返回 [dict]。

    参数
    ----
    line_offset : 传给本函数的 text 在**原始文件**中被截掉的行数。
        调用方（build）先剥掉 frontmatter 再分块；若不回补这个偏移，
        230/666 个带 frontmatter 的语料文件的行号会**整体前移**，
        指到错误的原文位置（比越界更隐蔽——它指向的是另一段真实存在的文字）。

    契约
    ----
    line_start / line_end 一律是**原始文件真实行号**（1-based），
    且 1 <= line_start <= line_end <= 原始文件真实行数。
    """
    raw_lines = text.split("\n")
    wrap = _wrap_index(raw_lines)
    lines = []
    for ln in raw_lines:
        lines.extend(_hard_wrap(ln, WRAP_LIMIT))

    def _real(i):
        """合成行 i → 原始文件真实行号（超出范围时钳到末行）。"""
        if i < 0:
            i = 0
        if i >= len(wrap):
            i = len(wrap) - 1
        return (wrap[i][2] if wrap else 1) + line_offset

    def _piece_bounds(i0, i1):
        """合成行区间 [i0, i1) → 该区间在原文中的字符起止（排他）；空区间返回 None。

        🔴 直接用**合成片段自己的起止**，而不是「真实行的整行区间」：折行会让一个块
        只覆盖某真实行的中间一段（如 5400 字符长行被切成 3 片，第 1 块只含第 1 片），
        此时「整行区间」会把不属于该块的内容算进来。片段起止表两件事都能表达。
        """
        if not wrap or i0 >= i1:
            return None
        i0 = max(0, min(i0, len(wrap) - 1))
        i1 = max(i0 + 1, min(i1, len(wrap)))
        return wrap[i0][0], wrap[i1 - 1][1]

    def _content(i0, i1):
        """合成行区间 [i0, i1) 的正文切片（块正文一律 = 原文的连续切片）。

        🔴 直接按**片段字符区间**从原文本切，而不是把折行拼回去：
        这样正文里不会有 hard wrap 引入的假换行（旧版 `"\\n".join(cur)` 会在段落中途
        凭空多出换行），且与 char_start/char_end 两字段逐字节自洽。
        """
        b = _piece_bounds(i0, i1)
        return text[b[0]:b[1]].strip() if b else ""

    def _trimmed_bounds(i0, i1):
        """片段区间 → (去首尾空白后的正文, char_start, char_end)。

        🔴 char_start/char_end 必须与**块正文的字符范围**一致，不能直接用片段区间：
        片段区间含首尾空白（典型：起始片的前导换行、末片行尾换行），而正文是 strip 过的
        ⇒ 直接报片段区间会让 char_start 落在**上一行的换行符**上，`text[char_start:char_end]`
        比块正文多出若干空白，块正文也不再是该切片的子串（回指校验必然失败）。
        实测正是这条让「检索命中块的行号可回指」夹具报 FAIL。
        """
        b = _piece_bounds(i0, i1)
        if not b:
            return "", None, None
        raw = text[b[0]:b[1]]
        lead = len(raw) - len(raw.lstrip())
        trail = len(raw) - len(raw.rstrip())
        return raw.strip(), b[0] + lead, b[1] - trail

    def _rec(i0, i1, head):
        """合成行区间 [i0, i1) → 块记录（行号映射回真实行号）。"""
        txt, c0, c1 = _trimmed_bounds(i0, i1)
        # 🔴 line_start/line_end 必须由**正文的字符区间**反推（而不是片段下标 i0/i1-1）：
        #    片段区间含首尾空白，_real(i1-1) 会指向**下一行的空串片段** ⇒ 报出的 line_end
        #    比实际内容多一行（实测块报 4-11，而第 11 行是文件末尾空行，内容其实止于第 10 行）。
        #    行号多一行比少一行更坏：按行号取原文会拿到不属于该块的内容。
        if c0 is None:
            return {"line_start": _real(i0), "line_end": _real(i1 - 1),
                    "char_start": None, "char_end": None,
                    "heading": head, "text": ""}
        return {"line_start": _line_of_start(c0), "line_end": _line_of_end(c1),
                "char_start": c0, "char_end": c1,
                "heading": head, "text": txt}

    def _real_of_char(pos):
        """字符下标 pos（**排他**末端）→ 它所属的真实行号。

        🔴 这里不能用「end = pos - 1 再查」，因为构建里这个函数要服务两种语义：
          · 起点：char_start 处的字符**属于**哪一行 —— 应查 pos 本身；
          · 终点：char_end 是排他的，最后一个字符在 pos-1 —— 应查 pos-1。
        用 pos-1 统一处理会把「正好落在行首的起点」错算成**上一行**：实测块报
        line_start=624 而正文实际在第 62 行（该文件有 624 行，624 是最后一行）。
        故按 pos 处字符是否为换行来分流：换行符归其所在行，其余字符归它出现的行。
        """
        if not text:
            return line_offset + 1
        i = pos if pos < len(text) else len(text) - 1
        if text[i] != "\n":
            for s, e, rl in wrap:
                if s <= i < e:
                    return rl + line_offset
        j = i - 1 if text[i] == "\n" else i
        if j < 0:
            j = 0
        for s, e, rl in wrap:
            if s <= j < e:
                return rl + line_offset
        for s, e, rl in reversed(wrap):
            if e > s:
                return rl + line_offset
        return (wrap[-1][2] if wrap else 1) + line_offset

    def _line_of_start(c0):
        """块正文起始字符所在行（起点语义：查 pos 本身）。"""
        return _real_of_char(c0)

    def _line_of_end(c1):
        """块正文末字符所在行（排他末端语义：查 pos-1，但换行符归其所在行）。"""
        i = c1 if c1 < len(text) else len(text) - 1
        if i < 0:
            i = 0
        if text and text[i] == "\n":
            return _real_of_char(i + 1)          # 换行符属于它结束的那一行
        return _real_of_char(i)

    # 先按标题行切段
    marks = []
    for i, ln in enumerate(lines):
        m = _H_RE.match(ln)
        if m and len(m.group(1)) <= 3:
            marks.append((i, m.group(2).strip()))
    if not marks or marks[0][0] != 0:
        marks.insert(0, (0, ""))

    chunks = []
    for idx, (start, head) in enumerate(marks):
        end = marks[idx + 1][0] if idx + 1 < len(marks) else len(lines)
        # 判「段是否够长」要看**真实正文**长度：折行拼接会虚增字符数（每折一行多 1 字符）
        seg = _content(start, end)
        if not seg:
            continue
        base_head = head
        if len(seg) <= MAX_CHARS:
            chunks.append(_rec(start, end, base_head))
            continue
        cur_start, size = start, 0
        # last_emitted = 下一条「尚未被任何已落盘块整片包含」的合成行（排他上界）。
        # 🔴 重叠回退不得跨过它：跨过就意味着把上一条已整片落盘的合成行重新取一遍，
        #    而回退跨度（片长）大于 OVERLAP 时这一取就是整片（最长 WRAP_LIMIT），
        #    块正文因此变成「累加前缀」——实测该形态下 max(chars) 达 MAX_CHARS+2200，
        #    且块间行号区间互相包含、完全无法回指。到边界就放弃重叠（宁可不重叠，
        #    不可原地打转），这样每个块的行区间都是单调前进的、可回指的。
        last_emitted = start
        j = start
        while j < end:
            size += len(lines[j]) + 1
            if size >= TARGET_CHARS:
                chunks.append(_rec(cur_start, j + 1, base_head))
                last_emitted = j + 1
                # 重叠：从 j 往前回取约 OVERLAP 字符（**不含 j 本身**）
                k, bs = j - 1, 0
                while k >= start and bs < OVERLAP:
                    bs += len(lines[k]) + 1
                    k -= 1
                if k + 1 < last_emitted:
                    # 🔴 回退越过了 last_emitted ⇒ 回退跨度 ≥ 一整个合成片，
                    #    再取回来就是把上一条已落盘的片**整片重复一遍**。
                    #    该形态下 max(chars) 实测达 MAX_CHARS+2200，且块间行区间互相包含
                    #    （回指原文完全失真）。故此处**放弃重叠**，从 last_emitted 起新块：
                    #    宁可少 200 字符重叠，不可产出无法回指的巨型块。
                    cur_start, size = last_emitted, 0
                else:
                    cur_start, size = k + 1, bs
            j += 1
        if _content(cur_start, end):
            chunks.append(_rec(cur_start, end, base_head))

    # 合并过短的块
    merged = []
    for c in chunks:
        if merged and len(c["text"]) < MIN_CHARS:
            prev = merged[-1]
            # 🔴 不再补插 "### {heading}"：小节的标题行**本来就在** c["text"] 里
            #    （段是按标题行切的，标题行是段的第一行）。补插会让块正文出现
            #    "### X" 与 "## X" 连续两行的伪标题，并让块正文不再是原文的连续切片
            #    （char 区间无法覆盖它）——回指原文时看到的文字与块内文字对不上。
            # 合并后行号/字符区间取**并集**：否则合并块的 line_end 会小于它实际覆盖的
            # 最后一行，回指原文时会少覆盖一段（内容在块里、行号却指不到）。
            # 头部的 line_start/char_start 同理必须取 min——首块被并入次块时（块序
            # 不一定等于位置序：重叠回退会让后一块的起点更靠前），若只更新尾部，
            # 合并块的 line_start 会**大于**它正文的起点，回指直接失效。
            prev["line_start"] = min(prev["line_start"], c["line_start"])
            prev["line_end"] = max(prev["line_end"], c["line_end"])
            if prev.get("char_start") is not None and c.get("char_start") is not None:
                prev["char_start"] = min(prev["char_start"], c["char_start"])
                prev["char_end"] = max(prev["char_end"], c["char_end"])
                prev["text"] = text[prev["char_start"]:prev["char_end"]]
        else:
            merged.append(dict(c))
    # 🔴 合并会把**位置更早**的块并入次块（重叠回退让后一块的起点可能更靠前），
    #    于是 merged 里的块序不再是位置序：实测出现过 line_start=12 的块排在
    #    line_start=1 的块之前，消费方读到 `range(12, 11)` 这种自相矛盾的行号区间
    #    （`{line_start}-{line_end}` 的引用格式直接反了）。故此处必须按位置排序，
    #    让块序、行号区间、id 编号三者一致。
    merged.sort(key=lambda c: (c.get("char_start") if c.get("char_start") is not None
                               else 1 << 60))
    out = []
    for i, c in enumerate(merged):
        # 只丢弃「既无标题又极短」的残渣；带标题的引言块要保留（它承载文档主旨）
        if len(c["text"]) < 60 and not c["heading"]:
            continue
        out.append({
            "id": f"{path}#{i}",
            "path": path,
            # 🔴 真实行号（原始文件 1-based），消费方据此可直接定位原文
            "line_start": c["line_start"],
            "line_end": c["line_end"],
            # 字符区间：line_start/line_end 的精度补充。折行可能让一个块只覆盖某行的
            # 中间一段，此时「块 = 整行区间」并不成立——有字符区间才能逐字节核对块正文。
            "char_start": c["char_start"],
            "char_end": c["char_end"],
            "heading": c["heading"],          # 不再截断：截断会静默丢字（下游按全名比对会失配）
            "chars": len(c["text"]),
            "text": c["text"],
        })
    return out


# ---------------------------------------------------------------- 证据元数据继承

def raw_to_source_map():
    """raw 路径 → source 页名（从 meta_full.json 的 sources 字段反查）。

    这样每个区块都能带上它所属来源页的证据强度，检索原文时限定词不丢。
    """
    m = {}
    if not os.path.exists(K.FULL_PATH):
        return m
    try:
        with open(K.FULL_PATH, "r", encoding="utf-8") as f:
            pages = json.load(f).get("pages", {})
    except Exception:                            # noqa: BLE001
        return m
    # wiki 与 projects 的 source 卡都可能是 raw 的证据限定词来源
    for page, row in pages.items():
        if row.get("type") != "source" or not row.get("path"):
            continue
        path = os.path.join(K.VAULT, *row["path"].split("/"))
        if not os.path.isfile(path):
            continue
        fm_raw, _ = K.split_frontmatter(K.read_text(path))
        fm = K.parse_frontmatter(fm_raw)
        for s in (fm.get("sources") or []):
            mm = re.search(r"\[\[(raw/[^\]]+?)\]\]", str(s))
            if mm:
                tgt = mm.group(1).replace("\\", "/")
                if tgt.endswith(".md"):
                    tgt = tgt[:-3]
                m.setdefault(tgt, page)
    return m


EVIDENCE_FIELDS = ("evidence_base", "source_reliability", "si_status")


def source_evidence(page):
    if not page:
        return {}
    rel = K.page_path_for_type(page, "source")
    p = os.path.join(K.VAULT, *rel.split("/")) if rel else ""
    if not p or not os.path.exists(p):
        return {}
    fm_raw, _ = K.split_frontmatter(K.read_text(p))
    fm = K.parse_frontmatter(fm_raw)
    out = {}
    for k in EVIDENCE_FIELDS:
        v = fm.get(k)
        if v:
            out["ev_" + k] = str(v)[:160]
    return out


# ---------------------------------------------------------------- 构建

def iter_corpus_files():
    for d in CORPUS_DIRS:
        base = os.path.join(K.VAULT, *d.split("/"))
        if not os.path.isdir(base):
            continue
        for dp, dn, fn in os.walk(base):
            dn[:] = [x for x in dn if x not in EXCLUDE_SEGMENTS]
            for f in sorted(fn):
                if f.lower().endswith(".md"):
                    yield os.path.relpath(os.path.join(dp, f), K.VAULT).replace("\\", "/")


def build():
    t0 = time.time()
    os.makedirs(CORPUS_DIR, exist_ok=True)
    r2s = raw_to_source_map()
    ev_cache = {}
    chunks = []
    file_hashes = {}
    n_files = 0
    char_mismatch = 0        # char_* 偏移无法在全文上取回正文的块数（见下面自证）
    for rel in iter_corpus_files():
        if any(seg in rel.split("/") for seg in EXCLUDE_SEGMENTS):
            continue
        n_files += 1
        text = K.read_text(os.path.join(K.VAULT, *rel.split("/")))
        file_hashes[rel] = hashlib.sha256(text.encode("utf-8")).hexdigest()
        # 只对**正文**分块：frontmatter（title/source/author/created…）不是知识内容，
        # 混进块里既污染检索（实测会靠 YAML 字段命中），也挤占块长。
        _, body = K.split_frontmatter(text)
        # 🔴 剥掉 frontmatter 会丢掉若干行，必须把偏移传给分块器，否则行号会整体前移
        #    （实测 230/666 个语料文件带 frontmatter）。这里按字符差算行数差，
        #    而不是去数 frontmatter 的行——差值法不依赖 frontmatter 的具体形态。
        fm_lines = text[:len(text) - len(body)].count("\n")
        fm_shift = len(text) - len(body)
        for c in split_chunks(body, rel, line_offset=fm_lines):
            key = c["path"][:-3] if c["path"].endswith(".md") else c["path"]
            page = r2s.get(key) or r2s.get(c["path"])
            if page and page not in ev_cache:
                ev_cache[page] = source_evidence(page)
            c.update(ev_cache.get(page, {}))
            if page:
                c["source_page"] = page
            # 🔴 2026-10-10：把 char 偏移从**正文坐标**搬到**全文坐标**。
            #    分块是在 `body`（已剥 frontmatter）上做的，于是 char_start/char_end 原本是
            #    **正文内**偏移；而文档说的是"该块在**原文**中的字符区间"。
            #    后果（实测）：33/38 带 frontmatter 的文件里 `read_text(p)[cs:ce]` 取到的是
            #    **错位的文字**——对 35% 的语料文件静默失真，且字段看着权威。
            #    实测依据：25472 块中 `body[cs:ce]==text` 命中 99.7%，而 `full[cs:ce]==text`
            #    只命中 75.1% ⇒ 证实基准是 body。
            #    连同下面的自证一起改：偏移必须让 `read_text()[cs:ce]` 也取得到该块正文。
            if c.get("char_start") is not None:
                c["char_start"] += fm_shift
            if c.get("char_end") is not None:
                c["char_end"] += fm_shift
            # 写前自证：偏移必须真的能在**全文**上取回这段正文。
            #    不用断言直接崩——先统计，由 build() 结束时决定怎么报（见 char_mismatch）。
            if c.get("char_start") is not None and text[c["char_start"]:c["char_end"]] != c["text"]:
                char_mismatch += 1
            chunks.append(c)

    # 倒排索引
    doc_texts = []
    for c in chunks:
        doc_texts.append(f'{c.get("heading","")} {c["text"]}')
    doc_tf = [K.to_tf(K.tokenize(t)) for t in doc_texts]
    names = [str(i) for i in range(len(chunks))]
    tf_map = {names[i]: doc_tf[i] for i in range(len(names))}
    postings, df = K.build_postings(tf_map, names)
    doc_len = {n: sum(tf_map[n].values()) for n in names}

    with open(CHUNKS_PATH + ".tmp", "w", encoding="utf-8", newline="\n") as f:
        for c in chunks:
            f.write(K.json_dumps(c, ensure_ascii=False) + "\n")
    os.replace(CHUNKS_PATH + ".tmp", CHUNKS_PATH)
    K.write_json_atomic(BM25_PATH,
                        {"_version": 1, "doc_names": names, "doc_len": doc_len,
                         "df": df, "n_docs": len(names), "postings": postings},
                        ensure_ascii=False, separators=(",", ":"))
    meta = {"built_at": time.strftime("%Y-%m-%d %H:%M:%S"),
            "files": n_files, "chunks": len(chunks),
            "file_hashes": file_hashes,
            "vocab": len(df), "dirs": CORPUS_DIRS,
            "target_chars": TARGET_CHARS,
            "avg_chunk_chars": round(sum(c["chars"] for c in chunks)
                                     / max(1, len(chunks)), 1),
            "with_evidence": sum(1 for c in chunks if c.get("source_page")),
            "char_offset_mismatch": char_mismatch,
            "elapsed_s": round(time.time() - t0, 1)}
    K.write_json_atomic(META_PATH, meta, ensure_ascii=False, indent=1)
    # 把 char 偏移的可回指性**报出来**，不藏在 meta 里等人翻：
    #   0 是期望值；非 0 说明 `read_text(p)[char_start:char_end]` 取不到该块正文
    #   （2026-10-10 修复前全库 6332/25472 不匹配，因为偏移是"正文坐标"而字段文档说"原文坐标"）。
    if char_mismatch:
        print(f"[warn] char_start/char_end 无法在全文上取回正文的块: {char_mismatch}"
              f"（{len(chunks)} 块中）—— 该字段的可回指性不成立，消费前请核对",
              file=sys.stderr)
    else:
        print(f"[ok] char_start/char_end 可回指全文：{len(chunks)} 块全部通过")
    return meta


# ---------------------------------------------------------------- 检索

_CACHE = {}


def _cache_signature():
    return tuple((p, os.path.getmtime(p), os.path.getsize(p)) if os.path.exists(p)
                 else (p, None, None) for p in (CHUNKS_PATH, BM25_PATH, META_PATH))


def load_corpus():
    signature = _cache_signature()
    if _CACHE and _CACHE.get("signature") == signature:
        return _CACHE
    if not (os.path.exists(CHUNKS_PATH) and os.path.exists(BM25_PATH)):
        return None
    _CACHE.clear()
    with open(BM25_PATH, encoding="utf-8") as f:
        _CACHE["bm"] = json.load(f)
    chunks = []
    with open(CHUNKS_PATH, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line:
                chunks.append(json.loads(line))
    _CACHE["chunks"] = chunks
    _CACHE["signature"] = signature
    return _CACHE


def check_corpus_freshness():
    """全量核对文件集合与同名内容；供 doctor/收尾门禁调用。"""
    if not os.path.exists(META_PATH):
        return {"ok": False, "reason": "corpus meta 不存在"}
    with open(META_PATH, encoding="utf-8") as f:
        meta = json.load(f)
    expected = meta.get("file_hashes")
    if not isinstance(expected, dict):
        return {"ok": False, "reason": "旧语料索引无内容哈希，请重建"}
    current = set(iter_corpus_files())
    missing = sorted(current - set(expected))
    stale = sorted(set(expected) - current)
    changed = []
    for rel in sorted(current & set(expected)):
        text = K.read_text(os.path.join(K.VAULT, *rel.split("/")))
        digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
        if digest != expected[rel]:
            changed.append(rel)
    return {"ok": not (missing or stale or changed), "missing": missing,
            "stale": stale, "changed": changed, "files": len(current)}


def search(query, k=8, expand_alias=True):
    """分块检索。返回 [{score, path, line_start, line_end, heading, snippet, ...}]。"""
    C = load_corpus()
    if not C:
        return []
    bm = C["bm"]
    chunks = C["chunks"]
    import math
    names = bm["doc_names"]
    doc_len = bm["doc_len"]
    df = bm["df"]
    N = bm["n_docs"]
    avgdl = sum(doc_len.values()) / max(1, len(doc_len))
    postings = bm["postings"]

    qt = K.tokenize(query)
    if expand_alias:
        try:
            import kb_search as KS
            meta, _ = KS.load_index()
            for a, c in KS.resolve_aliases(query, meta.get("alias_map", {}))[:3]:
                qt.extend(K.tokenize(c))
        except Exception:                        # noqa: BLE001
            pass

    scores = defaultdict(float)
    k1, b = 1.5, 0.75
    for t in set(qt):
        plist = postings.get(t)
        if not plist:
            continue
        n_t = df.get(t, len(plist))
        idf = max(0.0, math.log((N - n_t + 0.5) / (n_t + 0.5) + 1.0))
        for di, f in plist:
            nm = names[di]
            dl = doc_len.get(nm, 1) or 1
            denom = f + k1 * (1 - b + b * dl / avgdl)
            scores[di] += idf * (f * (k1 + 1)) / denom

    ranked = sorted(scores.items(), key=lambda kv: -kv[1])[:k]
    out = []
    for di, sc in ranked:
        c = chunks[di]
        out.append({
            "score": round(sc, 3),
            "path": c["path"],
            "line_start": c["line_start"],
            "line_end": c["line_end"],
            "char_start": c.get("char_start"),
            "char_end": c.get("char_end"),
            "heading": c.get("heading", ""),
            "chars": c["chars"],
            "snippet": c["text"][:400].replace("\n", " "),
            "source_page": c.get("source_page", ""),
            "evidence_base": c.get("ev_evidence_base", ""),
            "source_reliability": c.get("ev_source_reliability", ""),
            "si_status": c.get("ev_si_status", ""),
        })
    return out


# ---------------------------------------------------------------- 自检夹具

def _selftest_line_mapping():
    """行号映射夹具：自包含（tempfile 合成目录），**绝不**在真实库上写。

    为什么必须独立成一个夹具（而不是并进 selftest 的临时文本）：
    行号缺陷有两类，且第二类比第一类隐蔽——
      ① 合成行号越过 EOF：用户回原文定位落到文件末尾之外，一眼能看出错；
      ② frontmatter 被剥离后行号未回补偏移：行号**指向另一段真实存在的文字**，
         不越界、不报错，只有逐行核对才发现（230/666 语料文件带 frontmatter）。
    ⇒ 故夹具同时断言「不越界」与「所指即所得」，并把两处旧行为都钉成反例。
    """
    import tempfile
    import shutil
    global CHUNKS_PATH, BM25_PATH, META_PATH, CORPUS_DIR
    ok = True
    print("  --- 行号映射夹具（tempfile 合成语料，不写真实库）---")

    def chk(cond, label):
        nonlocal ok
        print(f"  [{'ok' if cond else 'FAIL'}] {label}")
        ok = ok and cond

    # HEAD 旧实现（同一份代码的基线副本，放在 .qc/_baseline_kb_corpus_head.py）：
    # 反例必须**由旧行为反算**，否则「旧行为会怎样」只是我在注释里的一句断言，
    # 不是证据。基线不存在时降级为只报当前值（不让夹具因缺文件而失败）。
    base = None
    bpath = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                         "..", ".qc", "_baseline_kb_corpus_head.py")
    if os.path.exists(bpath):
        try:
            import importlib.util
            spec = importlib.util.spec_from_file_location("_kc_head_base", bpath)
            base = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(base)
        except Exception:                        # noqa: BLE001
            base = None

    tmp = K.make_temp_dir(prefix="kbcorpus_fix_")
    old_paths = {"CHUNKS_PATH": CHUNKS_PATH, "BM25_PATH": BM25_PATH,
                 "META_PATH": META_PATH, "CORPUS_DIR": CORPUS_DIR}
    try:
        # ---------- 反例1：5400 字符单行 —— 旧行为 max(line_end) > 真实行数 ----------
        long_line = "长" + "A" * 5400
        bad = "# 标题\n\n第二行\n第三行\n" + long_line + "\n结尾行\n"
        real_n = bad.count("\n") + 1
        bs = split_chunks(bad, "raw/text/repro.md")
        mx = max(c["line_end"] for c in bs)
        old_mx = (max(c["line_end"] for c in base.split_chunks(bad, "raw/text/repro.md"))
                  if base else None)
        chk(mx <= real_n,
            f"反例1 超长单行不再越过 EOF（真实 {real_n} 行；"
            f"旧行为最大行号={old_mx}，现最大={mx}）")
        if old_mx is not None:
            chk(old_mx > real_n,
                f"反例1-b 旧行为确实越界（{old_mx} > {real_n}）——证明该反例有效")

        # ---------- 反例2：含 frontmatter —— 旧行为行号整体前移 ----------
        fm_doc = ("---\ncreated: 2026-01-01\ntype: source\ntags: [x]\n"
                  "summary: \"s\"\n---\n\n# 正文标题\n\n第一段。\n\n第二段。\n")
        fm_raw, body = K.split_frontmatter(fm_doc)
        off = fm_doc[:len(fm_doc) - len(body)].count("\n")
        fcs = split_chunks(body, "raw/text/fm.md", line_offset=off)
        fl = fm_doc.split("\n")
        got_new = fl[fcs[0]["line_start"] - 1]
        old_first = (base.split_chunks(body, "raw/text/fm.md")[0]["line_start"]
                     if base else None)
        got_old = fl[old_first - 1] if old_first else None
        chk(got_new.startswith("# 正文标题"),
            f"反例2 frontmatter 后行号不再前移（偏移 {off} 行；"
            f"旧行为第 {old_first} 行={got_old!r}，"
            f"现第 {fcs[0]['line_start']} 行={got_new!r}）")
        if got_old is not None:
            chk(not got_old.startswith("#"),
                f"反例2-b 旧行为确实指错行（{got_old!r}）——证明该反例有效")

        # ---------- 反例3：文件末尾空缺行不得被算进 line_end ----------
        # 实测旧行为把 "…内容。\n\n"（末尾空行）报成覆盖到「空行那一行」，
        # 行号仍 ≤ 真实行数（不越界），但**行号所指的行没有该块的内容**；
        # 按行号取原文会拿到空白行。这类「不越界但指错」比越界更难发现。
        tail_doc = "# T\n\n内容。\n\n"
        td = tail_doc.split("\n")
        tcs = split_chunks(tail_doc, "raw/text/tail.md")
        last = max(tcs, key=lambda c: c["char_end"])
        old_last = (max(base.split_chunks(tail_doc, "raw/text/tail.md"),
                        key=lambda c: c["line_end"])["line_end"] if base else None)
        # 真实有内容的最后一行
        last_content_line = max(i + 1 for i, t in enumerate(td) if t.strip())
        chk(last["line_end"] == last_content_line,
            f"反例3 末尾空行不被算进 line_end（有内容的最后一行={last_content_line}；"
            f"旧行为={old_last}，现={last['line_end']}）")
        if old_last is not None:
            chk(old_last > last_content_line,
                f"反例3-b 旧行为确实多算一行（{old_last} > {last_content_line}）")

        # ---------- 反例4：连续空行 ----------
        gap_doc = "# T\n\n第一段。\n\n\n\n第二段。\n"
        gd = gap_doc.split("\n")
        gcs = split_chunks(gap_doc, "raw/text/gap.md")
        g_last = max(c["line_end"] for c in gcs)
        g_content = max(i + 1 for i, t in enumerate(gd) if t.strip())
        g_old = (max(c["line_end"] for c in base.split_chunks(gap_doc, "raw/text/gap.md"))
                 if base else None)
        chk(g_last <= g_content,
            f"反例4 连续空行不被算进 line_end（有内容的最后一行={g_content}；"
            f"旧行为={g_old}，现={g_last}）")
        chk(all(1 <= c["line_start"] <= c["line_end"] <= len(gd) for c in gcs),
            "反例4 全部行号仍在 1..真实行数 内")

        # ---------- 正例：无末尾换行的文件 ----------
        nonl = "# T\n\n甲。\n乙。\n丙。"
        ncs = split_chunks(nonl, "raw/text/nonl.md")
        chk(all(1 <= c["line_start"] <= c["line_end"] <= nonl.count("\n") + 1
                for c in ncs),
            f"正例 无末尾换行的文件行号不越界（真实行数={nonl.count(chr(10)) + 1}）")
        chk(any("丙。" in c["text"] for c in ncs), "正例 无末尾换行时末行内容未丢失")

        # ---------- 正例：行号 + 字符区间都必须真的指回原文 ----------
        doc = ("# 文档标题\n\n引入段落甲乙丙。\n\n## 第一节\n\n第一节内容。\n\n"
               "## 第二节\n\n第二节内容。\n\n## 第三节\n\n第三节内容。\n")
        tl = doc.split("\n")
        real_n = len(tl)
        cs = split_chunks(doc, "raw/text/ok.md")
        chk(bool(cs) and all(1 <= c["line_start"] <= c["line_end"] <= real_n
                             for c in cs),
            f"正例 全部行号落在 1..{real_n}")
        # 块正文必须是 **char 区间所指原文切片的子串**（允许 strip 掉首尾空白）。
        # 这正是「行号/字符区间能回指原文」的直接检验：块里出现原文没有的字，
        # 回指就会对不上。合并路径曾在这里栽过一次（补插 "### 小节" 伪标题）。
        chk(all(c["text"] in doc[c["char_start"]:c["char_end"]] for c in cs),
            "正例 块正文是 char 区间原文切片的子串（无凭空插入的文字）")
        chk(all(c["char_end"] > c["char_start"] for c in cs),
            "正例 字符区间非空（char_end > char_start）")
        # 块覆盖的**真实行区间内**必须真的出现该块正文的开头（可回指的最低要求）
        pointer_ok = all(
            c["text"][:12] in "\n".join(tl[c["line_start"] - 1:c["line_end"]])
            for c in cs if c["text"])
        chk(pointer_ok, "正例 按报出行号取原文，确能得到该块内容（不越界、不指错行）")

        # 行号 → 真实文本的核对（位置序，与块产出顺序无关）
        pos = sorted(cs, key=lambda c: c["char_start"])
        rl = [c["line_start"] for c in pos]
        chk(rl == sorted(rl) and rl[0] == 1,
            f"正例 按位置排序后行号单调且首块从第 1 行起（{rl}）")

        # ---------- 正例：行号覆盖并集 == 真实文本（不存在回指不到的盲区）----------
        drawn, recon = [], []
        for c in cs:
            drawn.extend(range(c["line_start"], c["line_end"] + 1))
            recon.append((c["char_start"], c["char_end"]))
        # 上界用「最后一条**有内容**的行」：文件末尾换行符会 split 出一个空串元素，
        # 它没有内容、也不该被任何块覆盖（块正文是 strip 过的，永远不会包含它）。
        last_content = max(i + 1 for i, t in enumerate(tl) if t.strip())
        chk(sorted(set(drawn)) == list(range(1, last_content + 1)),
            f"正例 块覆盖的真实行并集 == 1..{last_content}（无回指盲区；"
            f"文件末空行不计）")
        cut, gaps = 0, []
        for s, e in recon:
            if s > cut:
                gaps.append(doc[cut:s].strip())   # 落在所有字符区间之外的内容
            cut = max(cut, e)
        gaps.append(doc[cut:].strip())
        chk(not [g for g in gaps if g],
            f"正例 字符区间覆盖全部原文（缺口={[g[:20] for g in gaps if g]}）")

        # ---------- 正例：检索端到端（build → search）行号仍可回指 ----------
        tmp_d = os.path.join(tmp, "wiki", ".index", "corpus")
        os.makedirs(os.path.join(tmp, "raw", "text"), exist_ok=True)
        os.makedirs(tmp_d, exist_ok=True)
        globals().update({"CHUNKS_PATH": os.path.join(tmp_d, "chunks.jsonl"),
                          "BM25_PATH": os.path.join(tmp_d, "bm25.json"),
                          "META_PATH": os.path.join(tmp_d, "meta.json"),
                          "CORPUS_DIR": tmp_d})
        fn = os.path.join(tmp, "raw", "text", "sample.md")
        sdoc = ("---\ntype: source\n---\n"        # 故意带 frontmatter：同时验偏移
                "# 标题\n\n量子点敏化太阳能电池。\n\n"
                "## 方法\n\n旋涂法制备薄膜。\n")
        with open(fn, "w", encoding="utf-8", newline="") as f:
            f.write(sdoc)
        saved = {k: globals().get(k) for k in ("VAULT", "CORPUS_DIRS")}
        globals().update({"VAULT": tmp, "CORPUS_DIRS": ["raw/text"]})
        K.VAULT = tmp
        _CACHE.clear()
        try:
            m = build()
            res = search("旋涂法", k=3)
            sl = sdoc.split("\n")
            # 检索返回里**没有** text 字段（只有 snippet），故用 snippet 核对；
            # 曾误用 r["text"]（恒为 None）使该断言**恒假**——夹具自己先出了
            # 「用不存在的字段做判定」的错，与它要防的失效同型，故在此写明。
            # ⚠️ 两端都要取缀：snippet 是块的**开头**且可能以 "\n" 起头，
            #    而 line_start 指向的是块起点的真实行——行首尚未出现，故比对时必须
            #    同时允许「起始处的空行」不匹配。取 6 字符的正文前缀做「在区间内」判定。
            hit = bool(res) and any(
                r.get("snippet", "").strip().replace("\n", " ")[:6]
                in "\n".join(sl[r["line_start"] - 1:r["line_end"]]).replace("\n", " ")
                for r in res)
            chk(hit, f"正例 检索命中块的报出行号可回指原文"
                     f"（命中 {len(res)} 块，首块行 {res[0]['line_start'] if res else '-'}"
                     f"-{res[-1]['line_end'] if res else '-'}）")
            # 命中的块必须真的含查询词（否则「能回指」只是运气好，指到了别的段）
            chk(any("旋涂法" in r.get("snippet", "") for r in res),
                "正例 命中块的正文含查询词（不是靠行号凑出来的假阳性）")
            chk(all(1 <= r["line_start"] <= r["line_end"] <= len(sl) for r in res),
                f"正例 检索报出行号全在 1..{len(sl)}（含 frontmatter 偏移）")
            chk(m["chunks"] > 0, f"正例 build 产出 {m['chunks']} 块（临时语料）")
        finally:
            _CACHE.clear()
            K.VAULT = saved["VAULT"]
            for k, v in saved.items():
                globals()[k] = v
    finally:
        globals().update(old_paths)
        shutil.rmtree(tmp, ignore_errors=True)
    return ok


# ---------------------------------------------------------------- 自检

def selftest():
    print("=== kb_corpus --selftest ===")
    ok = True
    # 1) 分块：构造已知文本，核对块数/行号/标题
    doc = ("# 标题\n\n引言段落。\n\n## 方法\n\n" + "方法内容。" * 40 +
           "\n\n## 结果\n\n结果内容。\n")
    cs = split_chunks(doc, "raw/text/x.md")
    print(f"  分块数: {len(cs)}  首块: 行 {cs[0]['line_start']}-{cs[0]['line_end']}"
          f"  标题={cs[0]['heading']!r}")
    got_heads = [c["heading"] for c in cs]
    blob = "\n".join(c["heading"] + "\n" + c["text"] for c in cs)
    # 契约：小节标题要么成为该块的 heading，要么（当过短被并入前块时）
    # 以 "### 小节名" 的形式保留在正文里 —— 两种都算「没有丢标题」。
    good = all(s in blob for s in ("方法", "结果", "标题"))
    print(f"  [{'ok' if good else 'FAIL'}] 全部小节标题可检索到"
          f"（块 heading={got_heads}）")
    ok = ok and good
    # 2) 行号必须在文档范围内
    nl = doc.count("\n") + 1          # 真实行数（旧版用 count("\n")+2，比真实行数多 1，
    inrange = all(1 <= c["line_start"] <= c["line_end"] <= nl for c in cs)
    print(f"  [{'ok' if inrange else 'FAIL'}] 行号都在文档范围内（1..{nl}）")
    ok = ok and inrange
    # 3) 反例：超长无标题段落必须被切开（不能产出超大块）
    #    上界沿用 HEAD 就有的 MAX_CHARS+400 容差（HEAD 实测最长 3200）；
    #    收紧到 MAX_CHARS 会变成「顺手改契约」，把既有实现一并判红。
    big = "无标题长文。" * 900
    cs2 = split_chunks(big, "raw/text/y.md")
    maxlen = max(c["chars"] for c in cs2) if cs2 else 0
    good2 = len(cs2) > 1 and maxlen <= MAX_CHARS + 400
    print(f"  [{'ok' if good2 else 'FAIL'}] 超长段落被切分（{len(cs2)} 块，"
          f"最长 {maxlen} 字符 ≤ {MAX_CHARS}+400）")
    ok = ok and good2
    # 4) 空文本不得产出块
    empty = split_chunks("", "raw/text/z.md")
    print(f"  [{'ok' if not empty else 'FAIL'}] 空文本产出 0 块（反例）")
    ok = ok and not empty
    merged_doc = "# 标题\n" + "长" * 300 + "\n## 短\n短。"
    merged_chunks = split_chunks(merged_doc, "raw/text/merge.md")
    merged_exact = (len(merged_chunks) == 1 and all(
        c["text"] == merged_doc[c["char_start"]:c["char_end"]] for c in merged_chunks))
    print(f"  [{'ok' if merged_exact else 'FAIL'}] 短块合并保留原始空白与字符区间")
    ok = ok and merged_exact
    ok = ok and _selftest_line_mapping()
    # 5) 索引存在性
    if os.path.exists(META_PATH):
        with open(META_PATH, encoding="utf-8") as f:
            m = json.load(f)
        print(f"  索引: {m['files']} 文件 / {m['chunks']} 块 / 词表 {m['vocab']}"
              f" / 带证据元数据 {m['with_evidence']} 块")
    else:
        print("  [!] 尚未构建，跑 python tools/kb_corpus.py --build")
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="raw 全文分块检索")
    ap.add_argument("--build", action="store_true")
    ap.add_argument("--search", default="")
    ap.add_argument("--stats", action="store_true")
    ap.add_argument("-k", type=int, default=8)
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()
    if args.build:
        m = build()
        print(f"[ok] 语料索引已构建：{m['files']} 个文件 → {m['chunks']} 块"
              f"（平均 {m['avg_chunk_chars']} 字符，耗时 {m['elapsed_s']}s）")
        print(f"     词表 {m['vocab']}  带证据元数据 {m['with_evidence']} 块")
        for p in (CHUNKS_PATH, BM25_PATH):
            print(f"     {os.path.relpath(p, K.VAULT)}  "
                  f"{os.path.getsize(p)/1024/1024:.1f} MB")
        return 0
    if args.stats:
        if not os.path.exists(META_PATH):
            print("[--] 尚未构建")
            return 1
        with open(META_PATH, encoding="utf-8") as f:
            m = json.load(f)
        print(json.dumps(m, ensure_ascii=False, indent=1))
        return 0
    if args.search:
        res = search(args.search, k=args.k)
        if args.json:
            print(json.dumps({"query": args.search, "results": res},
                             ensure_ascii=False, indent=1))
            return 0
        print(f'语料检索: "{args.search}"   命中 {len(res)} 块\n')
        for i, r in enumerate(res, 1):
            print(f'{i:>2}. [{r["score"]}] {r["path"]}:{r["line_start"]}-{r["line_end"]}')
            if r.get("heading"):
                print(f'    § {r["heading"]}')
            if r.get("source_page"):
                bits = ['来源页 ' + K.cite_page(r['source_page'], 'source')]
                if r.get("evidence_base"):
                    bits.append(f'evidence_base={r["evidence_base"]}')
                if r.get("source_reliability"):
                    bits.append(f'可靠性={r["source_reliability"][:60]}')
                if r.get("si_status"):
                    bits.append(f'si={r["si_status"]}')
                print("    " + "  ".join(bits))
            print(f'    {r["snippet"][:180]}...')
            print()
        return 0
    ap.print_help()
    return 1


if __name__ == "__main__":
    K.console_encoding()
    sys.exit(main())
